import { eq, sql, type SQL } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
  type PgColumn,
} from 'drizzle-orm/pg-core';

/**
 * Holonet schema (PostgreSQL via Drizzle ORM).
 *
 * Conventions:
 * - UUID primary keys generated by gen_random_uuid() (pgcrypto extension,
 *   created by infra/docker/initdb/001-init.sql).
 * - created_at / updated_at with timezone. updated_at is maintained by the
 *   application — set it explicitly on every update.
 * - Status columns are text with CHECK constraints (easier to evolve than
 *   PostgreSQL enums).
 * - Every tenant-scoped table carries workspaceId and must be queried
 *   through workspaceFilter() (docs/PROJECT_RULES.md rule 18).
 * - JSONB for block props, template manifests, AI output, design tokens,
 *   and metadata.
 * - Never store plaintext passwords (users.passwordHash only).
 */

/* ------------------------------- users ------------------------------- */

export type UserRole = 'admin' | 'member';
export type UserStatus = 'active' | 'disabled';

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    email: text('email').notNull().unique(),
    /** Scrypt or bcrypt hash only — plaintext passwords are never stored. */
    passwordHash: text('password_hash').notNull(),
    role: text('role').$type<UserRole>().notNull().default('member'),
    status: text('status').$type<UserStatus>().notNull().default('active'),
    /** MFA fields are stored for a future phase — MFA is not implemented yet. */
    mfaSecret: text('mfa_secret'),
    mfaEnabled: boolean('mfa_enabled').notNull().default(false),
    mfaRecoveryCodes: text('mfa_recovery_codes').array(),
    lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
    /** Bumped on logout / password reset to invalidate existing sessions. */
    tokenVersion: integer('token_version').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('users_role_check', sql`${table.role} in ('admin', 'member')`),
    check('users_status_check', sql`${table.status} in ('active', 'disabled')`),
    index('users_status_idx').on(table.status),
  ],
);

/* ---------------------------- workspaces ----------------------------- */

export type WorkspaceStatus = 'active' | 'suspended' | 'deleted';
export type WorkspaceSettings = Record<string, unknown>;

export const workspaces = pgTable(
  'workspaces',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    name: text('name').notNull(),
    slug: text('slug').notNull().unique(),
    status: text('status').$type<WorkspaceStatus>().notNull().default('active'),
    settings: jsonb('settings').$type<WorkspaceSettings>().notNull().default({}),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('workspaces_status_check', sql`${table.status} in ('active', 'suspended', 'deleted')`),
    index('workspaces_status_idx').on(table.status),
  ],
);

/* -------------------------- workspace_members ------------------------ */

export type WorkspaceMemberRole = 'owner' | 'admin' | 'editor' | 'viewer';
export type WorkspaceMemberStatus = 'active' | 'disabled';

export const workspaceMembers = pgTable(
  'workspace_members',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role').$type<WorkspaceMemberRole>().notNull().default('editor'),
    status: text('status').$type<WorkspaceMemberStatus>().notNull().default('active'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'workspace_members_role_check',
      sql`${table.role} in ('owner', 'admin', 'editor', 'viewer')`,
    ),
    check('workspace_members_status_check', sql`${table.status} in ('active', 'disabled')`),
    uniqueIndex('workspace_members_workspace_user_idx').on(table.workspaceId, table.userId),
    index('workspace_members_workspace_idx').on(table.workspaceId),
    index('workspace_members_user_idx').on(table.userId),
  ],
);

/* ------------------------------- sites ------------------------------- */

export type SiteStatus = 'draft' | 'published' | 'archived';
export type SiteSettings = Record<string, unknown>;

export const sites = pgTable(
  'sites',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    status: text('status').$type<SiteStatus>().notNull().default('draft'),
    templateVersionId: uuid('template_version_id').references(() => templateVersions.id, {
      onDelete: 'set null',
    }),
    primaryDomainId: uuid('primary_domain_id').references((): AnyPgColumn => domains.id, {
      onDelete: 'set null',
    }),
    settings: jsonb('settings').$type<SiteSettings>().notNull().default({}),
    publishedAt: timestamp('published_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('sites_status_check', sql`${table.status} in ('draft', 'published', 'archived')`),
    uniqueIndex('sites_workspace_slug_idx').on(table.workspaceId, table.slug),
    index('sites_workspace_idx').on(table.workspaceId),
    index('sites_status_idx').on(table.status),
  ],
);

/* ----------------------------- templates ----------------------------- */

export type TemplateStatus = 'draft' | 'published' | 'archived';

export const templates = pgTable(
  'templates',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    description: text('description'),
    status: text('status').$type<TemplateStatus>().notNull().default('draft'),
    category: text('category'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('templates_status_check', sql`${table.status} in ('draft', 'published', 'archived')`),
    uniqueIndex('templates_workspace_name_idx').on(table.workspaceId, table.name),
    index('templates_workspace_idx').on(table.workspaceId),
    index('templates_status_idx').on(table.status),
  ],
);

/* ------------------------- template_versions ------------------------- */

/** Minimal JSON shape of a template manifest (see @holonet/templates). */
export interface TemplateManifestJson {
  name: string;
  description?: string;
  /** Block definitions — content is untrusted data (rule 17). */
  blocks: Array<{ type: string; props?: Record<string, unknown> }>;
  [key: string]: unknown;
}

export const templateVersions = pgTable(
  'template_versions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    templateId: uuid('template_id')
      .notNull()
      .references(() => templates.id, { onDelete: 'cascade' }),
    /** Semantic version string, e.g. '1.0.0'. */
    version: text('version').notNull(),
    manifest: jsonb('manifest').$type<TemplateManifestJson>().notNull(),
    isCurrent: boolean('is_current').notNull().default(false),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    uniqueIndex('template_versions_template_version_idx').on(table.templateId, table.version),
    index('template_versions_template_idx').on(table.templateId),
  ],
);

/* ------------------------------- pages ------------------------------- */

export type PageStatus = 'draft' | 'published' | 'archived';
export type PageMeta = Record<string, unknown>;

export const pages = pgTable(
  'pages',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    /** Path within the site, e.g. '/' or '/about'. */
    path: text('path').notNull(),
    title: text('title').notNull(),
    status: text('status').$type<PageStatus>().notNull().default('draft'),
    meta: jsonb('meta').$type<PageMeta>().notNull().default({}),
    sortOrder: integer('sort_order').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('pages_status_check', sql`${table.status} in ('draft', 'published', 'archived')`),
    uniqueIndex('pages_site_path_idx').on(table.siteId, table.path),
    index('pages_site_idx').on(table.siteId),
    index('pages_status_idx').on(table.status),
  ],
);

/* ------------------------------- blocks ------------------------------ */

/** Block props — rendered by templates; content is untrusted data (rule 17). */
export type BlockProps = Record<string, unknown>;

export const blocks = pgTable(
  'blocks',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    pageId: uuid('page_id')
      .notNull()
      .references(() => pages.id, { onDelete: 'cascade' }),
    /** Denormalized for tenant-scoped queries (pages → sites → workspaces). */
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    props: jsonb('props').$type<BlockProps>().notNull().default({}),
    sortOrder: integer('sort_order').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [index('blocks_page_idx').on(table.pageId), index('blocks_site_idx').on(table.siteId)],
);

/* ------------------------------- assets ------------------------------ */

export type AssetKind = 'image' | 'css' | 'js' | 'font' | 'file';
export type AssetStatus = 'uploading' | 'ready' | 'deleted';

export const assets = pgTable(
  'assets',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** Nullable: workspace-level assets are shared across sites. */
    siteId: uuid('site_id').references(() => sites.id, { onDelete: 'set null' }),
    kind: text('kind').$type<AssetKind>().notNull(),
    /** OSS object key, always workspace-prefixed (rule 18/19). */
    storageKey: text('storage_key').notNull(),
    originalName: text('original_name'),
    contentType: text('content_type'),
    sizeBytes: bigint('size_bytes', { mode: 'number' }).notNull().default(0),
    status: text('status').$type<AssetStatus>().notNull().default('ready'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('assets_kind_check', sql`${table.kind} in ('image', 'css', 'js', 'font', 'file')`),
    check('assets_status_check', sql`${table.status} in ('uploading', 'ready', 'deleted')`),
    index('assets_workspace_idx').on(table.workspaceId),
    index('assets_site_idx').on(table.siteId),
    index('assets_status_idx').on(table.status),
  ],
);

/* -------------------------------- forms ------------------------------ */

export interface FormFieldDefinition {
  name: string;
  label: string;
  type: 'text' | 'email' | 'textarea' | 'select' | 'checkbox' | 'file';
  required?: boolean;
  options?: string[];
}

export type FormStatus = 'active' | 'disabled';

export const forms = pgTable(
  'forms',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    /** Denormalized for tenant-scoped queries (sites → workspaces). */
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    status: text('status').$type<FormStatus>().notNull().default('active'),
    fields: jsonb('fields').$type<FormFieldDefinition[]>().notNull().default([]),
    notificationEmail: text('notification_email'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('forms_status_check', sql`${table.status} in ('active', 'disabled')`),
    index('forms_workspace_idx').on(table.workspaceId),
    index('forms_site_idx').on(table.siteId),
  ],
);

/* --------------------------- form_submissions ------------------------ */

export type FormSubmissionStatus = 'new' | 'read' | 'archived' | 'spam';

export const formSubmissions = pgTable(
  'form_submissions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    formId: uuid('form_id')
      .notNull()
      .references(() => forms.id, { onDelete: 'cascade' }),
    /** Denormalized for tenant-scoped queries (forms → workspaces). */
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** Submission payload — untrusted visitor data (rule 17). */
    data: jsonb('data').$type<Record<string, unknown>>().notNull(),
    /** Hashed client IP for abuse prevention — raw IPs are never stored. */
    ipHash: text('ip_hash'),
    status: text('status').$type<FormSubmissionStatus>().notNull().default('new'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'form_submissions_status_check',
      sql`${table.status} in ('new', 'read', 'archived', 'spam')`,
    ),
    index('form_submissions_form_idx').on(table.formId),
    index('form_submissions_workspace_idx').on(table.workspaceId),
    index('form_submissions_status_idx').on(table.status),
  ],
);

/* ------------------------------- domains ----------------------------- */

export type DomainStatus = 'pending' | 'active' | 'failed' | 'removed';

export const domains = pgTable(
  'domains',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    siteId: uuid('site_id').references((): AnyPgColumn => sites.id, { onDelete: 'set null' }),
    hostname: text('hostname').notNull().unique(),
    isPrimary: boolean('is_primary').notNull().default(false),
    status: text('status').$type<DomainStatus>().notNull().default('pending'),
    dnsVerifiedAt: timestamp('dns_verified_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'domains_status_check',
      sql`${table.status} in ('pending', 'active', 'failed', 'removed')`,
    ),
    index('domains_workspace_idx').on(table.workspaceId),
    index('domains_site_idx').on(table.siteId),
    index('domains_status_idx').on(table.status),
  ],
);

/* ----------------------------- deployments --------------------------- */

export type DeploymentStatus = 'queued' | 'building' | 'uploading' | 'live' | 'failed';

export const deployments = pgTable(
  'deployments',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    /** Denormalized for tenant-scoped queries (sites → workspaces). */
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    status: text('status').$type<DeploymentStatus>().notNull().default('queued'),
    /** OSS key prefix under which the published files live. */
    storagePrefix: text('storage_prefix').notNull(),
    note: text('note'),
    errorMessage: text('error_message'),
    startedAt: timestamp('started_at', { withTimezone: true }),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'deployments_status_check',
      sql`${table.status} in ('queued', 'building', 'uploading', 'live', 'failed')`,
    ),
    index('deployments_site_idx').on(table.siteId),
    index('deployments_workspace_idx').on(table.workspaceId),
    index('deployments_status_idx').on(table.status),
  ],
);

/* ------------------------------ snapshots ---------------------------- */

export type SnapshotKind = 'site' | 'database' | 'import';
export type SnapshotStatus = 'creating' | 'ready' | 'failed' | 'expired';

export const snapshots = pgTable(
  'snapshots',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    siteId: uuid('site_id')
      .notNull()
      .references(() => sites.id, { onDelete: 'cascade' }),
    /** Snapshot of the published output for a deployment (rollback point). */
    deploymentId: uuid('deployment_id').references(() => deployments.id, { onDelete: 'set null' }),
    kind: text('kind').$type<SnapshotKind>().notNull().default('site'),
    /** Object key in the OSS private bucket. */
    storageKey: text('storage_key').notNull(),
    sizeBytes: bigint('size_bytes', { mode: 'number' }).notNull().default(0),
    status: text('status').$type<SnapshotStatus>().notNull().default('creating'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('snapshots_kind_check', sql`${table.kind} in ('site', 'database', 'import')`),
    check(
      'snapshots_status_check',
      sql`${table.status} in ('creating', 'ready', 'failed', 'expired')`,
    ),
    index('snapshots_workspace_idx').on(table.workspaceId),
    index('snapshots_site_idx').on(table.siteId),
    index('snapshots_deployment_idx').on(table.deploymentId),
    index('snapshots_kind_idx').on(table.kind),
  ],
);

/* ---------------------------- subscriptions -------------------------- */

export type SubscriptionStatus = 'trialing' | 'active' | 'past_due' | 'canceled';
export type BillingCycle = 'monthly' | 'annual';

export const subscriptions = pgTable(
  'subscriptions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    plan: text('plan').notNull(),
    status: text('status').$type<SubscriptionStatus>().notNull().default('trialing'),
    billingCycle: text('billing_cycle').$type<BillingCycle>().notNull().default('monthly'),
    currentPeriodStart: timestamp('current_period_start', { withTimezone: true }),
    currentPeriodEnd: timestamp('current_period_end', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'subscriptions_status_check',
      sql`${table.status} in ('trialing', 'active', 'past_due', 'canceled')`,
    ),
    check('subscriptions_cycle_check', sql`${table.billingCycle} in ('monthly', 'annual')`),
    index('subscriptions_workspace_idx').on(table.workspaceId),
    index('subscriptions_status_idx').on(table.status),
  ],
);

/* ------------------------------- payments ---------------------------- */

/** Statuses suitable for manual billing (no payment processor integration yet). */
export type PaymentStatus = 'pending' | 'paid' | 'failed' | 'refunded' | 'voided';
export type PaymentMethod = 'manual' | 'invoice' | 'card' | 'bank_transfer';

export const payments = pgTable(
  'payments',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    subscriptionId: uuid('subscription_id').references(() => subscriptions.id, {
      onDelete: 'set null',
    }),
    amount: numeric('amount', { precision: 12, scale: 2 }).notNull(),
    currency: text('currency').notNull().default('USD'),
    status: text('status').$type<PaymentStatus>().notNull().default('pending'),
    method: text('method').$type<PaymentMethod>().notNull().default('manual'),
    /** External invoice number / payment reference. */
    reference: text('reference'),
    paidAt: timestamp('paid_at', { withTimezone: true }),
    notes: text('notes'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'payments_status_check',
      sql`${table.status} in ('pending', 'paid', 'failed', 'refunded', 'voided')`,
    ),
    check(
      'payments_method_check',
      sql`${table.method} in ('manual', 'invoice', 'card', 'bank_transfer')`,
    ),
    index('payments_workspace_idx').on(table.workspaceId),
    index('payments_subscription_idx').on(table.subscriptionId),
    index('payments_status_idx').on(table.status),
  ],
);

/* ------------------------------ audit_logs --------------------------- */

export const auditLogs = pgTable(
  'audit_logs',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    /** Nullable: system-level events have no workspace. */
    workspaceId: uuid('workspace_id').references(() => workspaces.id, { onDelete: 'set null' }),
    actorUserId: uuid('actor_user_id').references(() => users.id, { onDelete: 'set null' }),
    action: text('action').notNull(),
    targetType: text('target_type'),
    targetId: uuid('target_id'),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    ipHash: text('ip_hash'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    index('audit_logs_workspace_idx').on(table.workspaceId),
    index('audit_logs_actor_idx').on(table.actorUserId),
    index('audit_logs_action_idx').on(table.action),
    index('audit_logs_created_idx').on(table.createdAt),
  ],
);

/* ---------------------------- security_events ------------------------ */

export type SecurityEventSeverity = 'info' | 'warning' | 'critical';

export const securityEvents = pgTable(
  'security_events',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id').references(() => workspaces.id, { onDelete: 'set null' }),
    userId: uuid('user_id').references(() => users.id, { onDelete: 'set null' }),
    /** e.g. 'login_failed', 'rate_limited', 'csrf_violation'. */
    eventType: text('event_type').notNull(),
    severity: text('severity').$type<SecurityEventSeverity>().notNull().default('info'),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'security_events_severity_check',
      sql`${table.severity} in ('info', 'warning', 'critical')`,
    ),
    index('security_events_workspace_idx').on(table.workspaceId),
    index('security_events_user_idx').on(table.userId),
    index('security_events_type_idx').on(table.eventType),
    index('security_events_severity_idx').on(table.severity),
  ],
);

/* -------------------------------- jobs ------------------------------- */

export type JobStatus = 'pending' | 'processing' | 'completed' | 'failed';
export type JobPayload = Record<string, unknown>;
export type JobResult = Record<string, unknown>;

export const jobs = pgTable(
  'jobs',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** e.g. 'site_build', 'backup', 'form_notification'. */
    type: text('type').notNull(),
    status: text('status').$type<JobStatus>().notNull().default('pending'),
    priority: integer('priority').notNull().default(0),
    attempts: integer('attempts').notNull().default(0),
    maxAttempts: integer('max_attempts').notNull().default(3),
    payload: jsonb('payload').$type<JobPayload>().notNull().default({}),
    result: jsonb('result').$type<JobResult>(),
    errorMessage: text('error_message'),
    lockedAt: timestamp('locked_at', { withTimezone: true }),
    /** Workers claim jobs where available_at <= now(). */
    availableAt: timestamp('available_at', { withTimezone: true }).defaultNow().notNull(),
    startedAt: timestamp('started_at', { withTimezone: true }),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'jobs_status_check',
      sql`${table.status} in ('pending', 'processing', 'completed', 'failed')`,
    ),
    index('jobs_workspace_idx').on(table.workspaceId),
    index('jobs_status_idx').on(table.status),
    index('jobs_type_idx').on(table.type),
    index('jobs_available_idx').on(table.availableAt),
  ],
);

/* ------------------------------ import_jobs -------------------------- */

export type ImportJobStatus =
  'pending' | 'fetching' | 'analyzing' | 'completed' | 'failed' | 'rejected';

export const importJobs = pgTable(
  'import_jobs',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    siteId: uuid('site_id').references(() => sites.id, { onDelete: 'set null' }),
    sourceUrl: text('source_url').notNull(),
    status: text('status').$type<ImportJobStatus>().notNull().default('pending'),
    /** AI provider name (AI_PROVIDER), or null for manual imports. */
    aiProvider: text('ai_provider'),
    stats: jsonb('stats').$type<Record<string, unknown>>().notNull().default({}),
    errorMessage: text('error_message'),
    startedAt: timestamp('started_at', { withTimezone: true }),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check(
      'import_jobs_status_check',
      sql`${table.status} in ('pending', 'fetching', 'analyzing', 'completed', 'failed', 'rejected')`,
    ),
    index('import_jobs_workspace_idx').on(table.workspaceId),
    index('import_jobs_site_idx').on(table.siteId),
    index('import_jobs_status_idx').on(table.status),
  ],
);

/* ----------------------------- ai_analyses --------------------------- */

export type AiAnalysisStatus = 'pending' | 'completed' | 'failed';
export interface TokenUsageJson {
  promptTokens?: number;
  completionTokens?: number;
  totalTokens?: number;
}

export const aiAnalyses = pgTable(
  'ai_analyses',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    importJobId: uuid('import_job_id').references(() => importJobs.id, { onDelete: 'set null' }),
    siteId: uuid('site_id').references(() => sites.id, { onDelete: 'set null' }),
    model: text('model').notNull(),
    /** Prompt input and AI output are untrusted data (rule 17). */
    input: jsonb('input').$type<unknown>(),
    output: jsonb('output').$type<unknown>().notNull(),
    tokenUsage: jsonb('token_usage').$type<TokenUsageJson>().notNull().default({}),
    status: text('status').$type<AiAnalysisStatus>().notNull().default('completed'),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    check('ai_analyses_status_check', sql`${table.status} in ('pending', 'completed', 'failed')`),
    index('ai_analyses_workspace_idx').on(table.workspaceId),
    index('ai_analyses_import_job_idx').on(table.importJobId),
    index('ai_analyses_site_idx').on(table.siteId),
  ],
);

/* ---------------------------- design_tokens -------------------------- */

export interface DesignTokenSet {
  colors?: Record<string, string>;
  fonts?: Record<string, string>;
  spacing?: Record<string, string>;
  radii?: Record<string, string>;
  [key: string]: unknown;
}

export const designTokens = pgTable(
  'design_tokens',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    siteId: uuid('site_id').references(() => sites.id, { onDelete: 'set null' }),
    templateId: uuid('template_id').references(() => templates.id, { onDelete: 'set null' }),
    name: text('name').notNull(),
    tokens: jsonb('tokens').$type<DesignTokenSet>().notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    uniqueIndex('design_tokens_scope_name_idx').on(table.workspaceId, table.siteId, table.name),
    index('design_tokens_workspace_idx').on(table.workspaceId),
    index('design_tokens_site_idx').on(table.siteId),
  ],
);

/* --------------------------- tenant isolation ------------------------ */

/* ------------------------- password_reset_tokens --------------------- */

export const passwordResetTokens = pgTable(
  'password_reset_tokens',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** SHA-256 hex of the raw reset token — the raw token is never stored. */
    tokenHash: text('token_hash').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    index('password_reset_tokens_user_idx').on(table.userId),
    index('password_reset_tokens_hash_idx').on(table.tokenHash),
    index('password_reset_tokens_expires_idx').on(table.expiresAt),
  ],
);

/**
 * Tenant isolation helper (rule 18): returns the SQL condition that scopes a
 * tenant table to one workspace. Every tenant-scoped query MUST use this:
 *
 *   db.select().from(sites).where(workspaceFilter(sites, workspaceId))
 */
export function workspaceFilter<T extends { workspaceId: PgColumn }>(
  table: T,
  workspaceId: string,
): SQL {
  return eq(table.workspaceId, workspaceId);
}
